  "summary": "The code contained a critical SQL injection vulnerability, missing error handling, and hardcoded configuration. The overall health is poor due to these security and stability risks. The refactored code implements parameterized queries, robust error handling, and environment-based configuration.",
  "fixed_code": "const express = require('express');\nconst mysql = require('mysql2/promise');\n\nconst app = express();\nconst pool = mysql.createPool({\n  host: process.env.DB_HOST,\n  user: process.env.DB_USER,\n  password: process.env.DB_PASS,\n  database: 'shop'\n});\n\n/**\n * @param {import('express').Request} req\n * @param {import('express').Response} res\n */\napp.get('/products', async (req, res) => {\n  try {\n    const term = req.query.q || '';\n    if (term.length > 100) return res.status(400).json({ error: 'Query too long' });\n\n    const [rows] = await pool.query('SELECT id, name, price FROM products WHERE name LIKE ? LIMIT 50', [`%${term}%`]);\n    res.json(rows);\n  } catch (err) {\n    console.error(err);\n    res.status(500).json({ error: 'Internal Server Error' });\n  }\n});\n\napp.listen(process.env.PORT || 3000);"
}
